"""H897 fixed number axis; output coverage/rank diagnostic on cached states."""
from run_bilin18_agreement_partner_number import ROOT,ART,SNAPSHOT,sha,load_full_model
from pathlib import Path
import json,time,torch,numpy as np
S='bilin18_fixed_axis_output_coverage'
@torch.inference_mode()
def main():
 start=time.time();torch.set_num_threads(6);paths={'runner':Path(__file__),'model':SNAPSHOT/'pytorch_model.bin','units':ART/'bilin18_number_unit_recovery_units.pt','captures':ART/'bilin18_number_transfer_screen_captures.pt'};hashes={k:sha(p) for k,p in paths.items()};cfg=dict(experiment='H897',hashes=hashes,axis='original_A',training_pairs={'four':list(range(8,12)),'eight':list(range(8,16))},training_formats={'A':['A'],'AB':['A','B'],'ABCDEF':list('ABCDEF')},ranks=[0,1,2,4,7],validation_pairs=list(range(7)),design='Task-only regular-noun discovery; disjoint irregular nouns all six formats and task/copy validation. Fixed originalA input axis/origin. Existing reused diagnostic data, not untouched confirmation. Rank7 random subspace control. No natural or reservedtest evaluation.');(ROOT/f'configs/{S}.json').write_text(json.dumps(cfg,indent=2)+'\n');panel=torch.load(paths['captures'],weights_only=False);U=torch.load(paths['units'],weights_only=False)['original_A'];model=load_full_model('cuda');mod=model.blocks[12].mlp;L,R,D=[m.weight.double() for m in [mod.Left,mod.Right,mod.Down]];b=U['b'].cuda();origin=U['origin'].cuda();ex=panel['examples'];X=torch.stack([panel['states'][i][12] for i in range(len(ex))]).double().cuda();u=X/(X.square().mean(-1,keepdim=True)+torch.finfo(torch.float32).eps).sqrt();t=u@b-origin;w=u-t[:,None]*b;C=((w@L.T)*(b@R.T)+(w@R.T)*(b@L.T))@D.T;fits={};records=[];orth=0.;compiler=0.;trainsets={};val=[i for i,e in enumerate(ex) if e['pair'] in cfg['validation_pairs']];assert len(val)==168
 gen=torch.Generator(device='cuda').manual_seed(897);random=torch.linalg.qr(torch.randn(1152,7,generator=gen,device='cuda',dtype=torch.float64)).Q.T
 for size,pairs in cfg['training_pairs'].items():
  for fmt,formats in cfg['training_formats'].items():
   name=size+'_'+fmt;ix=[i for i,e in enumerate(ex) if e['pair'] in pairs and e['family']=='task' and e['format'] in formats];assert not set(ix)&set(val);trainsets[name]=ix;mu=C[ix].mean(0);_,s,V=torch.linalg.svd(C[ix]-mu,full_matrices=False);V=V[:7];orth=max(orth,float((V@V.T-torch.eye(7,device='cuda')).abs().max()));fits[name]=dict(mu=mu.cpu(),basis=V.cpu(),indices=ix,singular_values=s.cpu())
   for mode in ['rank0','rank1','rank2','rank4','rank7','random7']:
    k=7 if mode=='random7' else int(mode[4:]);B=random if mode=='random7' else V[:k];a=((B@D)*(R@b))@L+((B@D)*(L@b))@R;encoder=a-(a@b)[:,None]*b;off=origin*(a@b)-B@mu;hat=mu+(u@encoder.T+off)@B;ref=mu+(C-mu)@B.T@B;compiler=max(compiler,float((hat-ref).norm()/ref.norm()))
    for i in val:
     e=ex[i];err=(hat[i]-C[i]).square().sum();energy=C[i].square().sum();target=U['cc'][1-e['order']].cuda()+U['mean_projection'].cuda()-origin;delta=target-t[i];records.append(dict(fit=name,training_endpoints=len(ix),mode=mode,index=i,pair=e['pair'],format=e['format'],family=e['family'],C_error_squared=float(err),C_energy=float(energy),native_write_error_squared=float(t[i].square()*err),native_write_energy=float(t[i].square()*energy),flip_write_error_squared=float(delta.square()*err),flip_write_energy=float(delta.square()*energy)))
 audits=dict(hashes_unchanged=all(sha(p)==hashes[k] for k,p in paths.items()),orthonormal_error=orth,compiled_encoder_relative=compiler,disjoint_nouns=True,validation_examples=len(val),whole_model_forwards=0,test_evaluations=0,finite=all(np.isfinite(r['native_write_error_squared']) for r in records));assert audits['hashes_unchanged'] and orth<1e-10 and compiler<1e-10 and audits['finite'];torch.save(fits,ART/f'{S}_fits.pt');(ART/f'{S}.json').write_text(json.dumps(dict(config=cfg,trainsets=trainsets,records=records,audits=audits,elapsed_seconds=time.time()-start),indent=2)+'\n');print(audits)
if __name__=='__main__':main()
